#!/usr/bin/env node
// Renders a 640x320 thumbnail card with Playwright for every public repo that has
// no committed thumbnail in public/project-media/. Replaces fetching GitHub's
// OpenGraph card service, which rate-limits (HTTP 429) far below our repo count.
//
// Output goes to public/project-media/generated/ (gitignored; regenerated by the
// daily deploy). Runs against the GitHub API, or REPOS_FIXTURE when set.
//
// Usage:  node scripts/capture-thumbnails.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';
import sharp from 'sharp';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const MEDIA = path.join(ROOT, 'public', 'project-media');
const OUT_DIR = path.join(MEDIA, 'generated');
const manifest = JSON.parse(fs.readFileSync(path.join(MEDIA, 'manifest.json'), 'utf-8'));

async function loadRepos() {
	if (process.env.REPOS_FIXTURE) return JSON.parse(fs.readFileSync(process.env.REPOS_FIXTURE, 'utf-8'));
	const token = process.env.GH_TOKEN ?? process.env.GITHUB_TOKEN;
	const headers = token ? { Authorization: `Bearer ${token}` } : {};
	const all = [];
	for (let page = 1; page <= 10; page++) {
		const res = await fetch(`https://api.github.com/users/milesburton/repos?per_page=100&type=owner&page=${page}`, { headers });
		if (!res.ok) throw new Error(`GitHub API HTTP ${res.status}`);
		const batch = await res.json();
		all.push(...batch);
		if (batch.length < 100) break;
	}
	return all;
}

const esc = (s) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);

const card = (repo) => `<!doctype html><meta charset="utf-8"><style>
	html,body{margin:0;width:640px;height:320px}
	body{box-sizing:border-box;padding:36px 40px;display:flex;flex-direction:column;justify-content:space-between;
		font:16px/1.45 -apple-system,'Segoe UI',Helvetica,Arial,sans-serif;color:#e6e9f2;
		background:radial-gradient(120% 120% at 0% 0%,#2a2f5c 0%,#12142a 60%,#0a0b18 100%)}
	h1{margin:0;font-size:38px;line-height:1.15;letter-spacing:-.01em;word-break:break-word}
	p{margin:14px 0 0;color:#aab0c8;font-size:18px}
	.meta{display:flex;gap:10px;font-size:15px;color:#8d94b3}
	.chip{padding:4px 12px;border:1px solid #3a4070;border-radius:999px}
</style><div><h1>${esc(clip(repo.name, 38))}</h1><p>${esc(clip(repo.description ?? 'Open-source project on GitHub', 120))}</p></div>
<div class="meta">${repo.language ? `<span class="chip">${esc(repo.language)}</span>` : ''}${repo.stargazers_count > 0 ? `<span class="chip">★ ${repo.stargazers_count}</span>` : ''}</div>`;

const repos = (await loadRepos()).filter((r) => !r.fork && !r.private && !r.archived && !(r.name in manifest));
fs.mkdirSync(OUT_DIR, { recursive: true });
const browser = await chromium.launch();
let made = 0;
try {
	const page = await browser.newPage({ viewport: { width: 640, height: 320 }, deviceScaleFactor: 1 });
	for (const repo of repos) {
		await page.setContent(card(repo));
		const png = await page.screenshot({ type: 'png' });
		fs.writeFileSync(path.join(OUT_DIR, `${repo.name}.jpg`), await sharp(png).jpeg({ quality: 80, progressive: true }).toBuffer());
		made++;
	}
} finally {
	await browser.close();
}
console.log(`generated ${made} thumbnail card(s)`);
